70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
74	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
75	     */
76	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
