135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        validateRequiredOwnerFields(ownerFieldsDto);
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
142	        owner.setTelephone(normalizedTelephone);
143	        owner.setEmail(normalizeEmail(owner.getEmail()));
144	        owner.setAddress(normalizeAddress(owner.getAddress()));
145	        LocalDate effectiveRegistrationDate =
146	            owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
147	        owner.setRegistrationDate(rollToBusinessDay(effectiveRegistrationDate));
148	        rejectDuplicateTelephone(normalizedTelephone);
149	        rejectDailyLimitReached(owner.getRegistrationDate());
150	        rejectCityAtCapacity(owner.getCity());
151	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
152	            assignHousehold(owner);
153	        } else {
154	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
155	        }
156	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
157	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
158	        this.clinicService.saveOwner(owner);
159	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
160	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        headers.setLocation(UriComponentsBuilder.newInstance()
163	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
164	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
165	    }
