260	
261	    /**
262	     * Builds the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
263	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3}
264	     * is the upper-cased first three letters of the owner's last name, and {@code NNNN} is a per-city
265	     * 4-digit zero-padded sequence equal to one more than the number of owners already in that city.
266	     * For example an owner named "Smithers" in "Springfield" created when 10 owners already live in
267	     * Springfield gets {@code 'SPR-SMI-0011'}.
268	     *
269	     * @param city the owner's city
270	     * @param lastName the owner's last name
271	     * @return the assigned customer code
272	     */
273	    /**
274	     * Counts how many existing owners share the given first and last name, compared
275	     * case-insensitively, at the moment before the new owner is persisted. The result is
276	     * stored on the owner as its {@code namesakeCount}, so it reflects the population as it
277	     * stood when the owner was created rather than being recomputed on later reads.
278	     *
279	     * @param firstName the first name of the owner being created
280	     * @param lastName the last name of the owner being created
281	     * @return the number of pre-existing owners with the same first and last name
282	     */
283	    private int countNamesakes(String firstName, String lastName) {
284	        String first = firstName == null ? "" : firstName;
285	        String last = lastName == null ? "" : lastName;
286	        return (int) this.clinicService.findAllOwners().stream()
287	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
288	                && last.equalsIgnoreCase(existing.getLastName()))
289	            .count();
290	    }
291	
292	    private String nextCustomerCode(String city, String lastName) {
293	        String cityLetters = city == null ? "" : city;
294	        String city3 = cityLetters.substring(0, Math.min(3, cityLetters.length())).toUpperCase(Locale.ROOT);
295	        String letters = lastName == null ? "" : lastName;
296	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
297	        String normalizedCity = normalizeForComparison(city);
298	        int sequence = (int) this.clinicService.findAllOwners().stream()
299	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
300	            .count() + 1;
301	        return String.format("%s-%s-%04d", city3, last3, sequence);
302	    }
303	
304	    /**
305	     * Rejects an owner payload that is missing or blank in any of the required fields
306	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
307	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
308	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
309	     * guard enforces the rule uniformly for every required field.
310	     *
311	     * @param ownerFieldsDto the submitted owner payload
312	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
313	     */
314	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
315	        List<String> invalidFields = new ArrayList<>();
316	        if (isBlank(ownerFieldsDto.getFirstName())) {
317	            invalidFields.add("firstName");
318	        }
319	        if (isBlank(ownerFieldsDto.getLastName())) {
320	            invalidFields.add("lastName");
321	        }
322	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
323	            invalidFields.add("address");
324	        }
325	        if (isBlank(ownerFieldsDto.getCity())) {
326	            invalidFields.add("city");
327	        }
328	        if (isBlank(ownerFieldsDto.getTelephone())) {
329	            invalidFields.add("telephone");
330	        }
331	        if (!invalidFields.isEmpty()) {
332	            throw new InvalidOwnerFieldsException(invalidFields);
333	        }
334	    }
335	
336	    private boolean isBlank(String value) {
337	        return value == null || value.isBlank();
338	    }
339	
340	    /**
341	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
342	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
343	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
344	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
345	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
346	     *
347	     * @param telephone the raw telephone value from the submitted owner payload
348	     * @return the normalized E.164 telephone number
349	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
350	     */
351	    private String normalizeTelephone(String telephone) {
352	        String raw = telephone == null ? "" : telephone.strip();
353	        boolean hasCountryCode = raw.startsWith("+");
354	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
355	        String digits;
356	        if (hasCountryCode) {
357	            digits = cleaned.substring(1);
358	        } else {
359	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
360	            digits = "61" + national;
361	        }
362	        if (!digits.matches("[0-9]{8,15}")) {
363	            throw new InvalidOwnerFieldsException(List.of("telephone"));
364	        }
365	        return "+" + digits;
366	    }
367	
368	    /**
369	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
370	     * returning {@code null} when the value cannot form a valid E.164 number.
371	     *
372	     * @param telephone an existing owner's stored telephone value
373	     * @return the E.164 form, or {@code null} if it cannot be normalized
374	     */
375	    private String toE164OrNull(String telephone) {
376	        try {
377	            return normalizeTelephone(telephone);
378	        } catch (InvalidOwnerFieldsException ex) {
379	            return null;
380	        }
381	    }
382	
383	    /**
384	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
385	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
386	     * accepted value is trimmed and lower-cased before it is stored and returned.
387	     *
388	     * @param email the raw email value from the submitted owner payload, may be {@code null}
389	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
390	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
391	     */
392	    private String normalizeEmail(String email) {
393	        if (email == null) {
394	            return null;
395	        }
396	        String trimmed = email.strip();
397	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
398	            throw new InvalidOwnerFieldsException(List.of("email"));
399	        }
400	        return trimmed.toLowerCase(Locale.ROOT);
401	    }
402	
403	    /**
404	     * Rejects creating an owner whose E.164 telephone is already used by any other owner.
405	     * Existing owners' telephones are converted to E.164 form before comparison so that
406	     * differently-formatted representations of the same number are treated as duplicates.
407	     *
408	     * @param normalizedTelephone the E.164 telephone of the owner being created
409	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same E.164 telephone
410	     */
411	    private void rejectDuplicateTelephone(String normalizedTelephone) {
412	        boolean duplicate = this.clinicService.findAllOwners().stream()
413	            .map(Owner::getTelephone)
414	            .filter(telephone -> telephone != null)
415	            .map(this::toE164OrNull)
416	            .filter(telephone -> telephone != null)
417	            .anyMatch(normalizedTelephone::equals);
418	        if (duplicate) {
419	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
420	        }
421	    }
422	
423	    /**
424	     * The maximum number of owners a single city may contain. Once a city already holds this many
425	     * owners, creating another owner in that city is rejected.
426	     */
427	    private static final int MAX_OWNERS_PER_CITY = 50;
428	
429	    /**
430	     * Rejects creating an owner in a city that already contains {@link #MAX_OWNERS_PER_CITY} or more
431	     * owners. Existing owners' cities are compared case-insensitively with surrounding and repeated
432	     * internal whitespace collapsed (see {@link #normalizeForComparison}), matching the per-city
433	     * counting used elsewhere.
434	     *
435	     * @param city the city of the owner being created
436	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
437	     */
438	    /**
439	     * The maximum number of owners that may be registered on a single day. Once this many owners
440	     * already share a {@code registrationDate}, creating another owner for that day is rejected.
441	     */
442	    private static final int MAX_OWNERS_PER_DAY = 100;
443	
444	    /**
445	     * Rejects creating an owner on a day that has already reached {@link #MAX_OWNERS_PER_DAY} or more
446	     * owner registrations. Existing owners are counted by their {@code registrationDate} matching the
447	     * registration date of the owner being created.
448	     *
449	     * @param registrationDate the registration date of the owner being created
450	     * @throws DailyOwnerLimitExceededException if the day has already reached the maximum number of owners
451	     */
452	    /**
453	     * Rolls an effective registration date forward onto a business day. A registration date must fall
454	     * on a weekday: when the supplied or defaulted date is a Saturday or Sunday it is rolled forward to
455	     * the next Monday and that adjusted date becomes the owner's {@code registrationDate}. A weekday date
456	     * is returned unchanged. Every value derived from the registration date (the daily create-limit
457	     * count, the membership number's year segment, and so on) uses this adjusted date.
458	     *
459	     * @param date the effective registration date (supplied in the request or defaulted to the server date)
460	     * @return the same date if it is a weekday, otherwise the following Monday
461	     */
462	    private LocalDate rollToBusinessDay(LocalDate date) {
463	        DayOfWeek day = date.getDayOfWeek();
464	        if (day == DayOfWeek.SATURDAY) {
465	            return date.plusDays(2);
466	        }
467	        if (day == DayOfWeek.SUNDAY) {
468	            return date.plusDays(1);
469	        }
470	        return date;
471	    }
472	
473	    private void rejectDailyLimitReached(LocalDate registrationDate) {
474	        long ownersToday = this.clinicService.findAllOwners().stream()
475	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
476	            .count();
477	        if (ownersToday >= MAX_OWNERS_PER_DAY) {
478	            throw new DailyOwnerLimitExceededException(registrationDate);
479	        }
480	    }
481	
482	    private void rejectCityAtCapacity(String city) {
483	        String normalizedCity = normalizeForComparison(city);
484	        long ownersInCity = this.clinicService.findAllOwners().stream()
485	            .filter(existing -> normalizedCity.equals(normalizeForComparison(existing.getCity())))
486	            .count();
487	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
488	            throw new OwnerCityCapacityExceededException(city);
489	        }
490	    }
491	
492	    /**
493	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
494	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
495	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
496	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
497	     *
498	     * @param lastName the last name of the owner being created
499	     * @param address the address of the owner being created
500	     * @throws DuplicateOwnerHouseholdException if another owner shares the same last name and address
501	     */
502	    private void rejectDuplicateHousehold(String lastName, String address) {
503	        String normalizedLastName = normalizeForComparison(lastName);
504	        String normalizedAddress = normalizeAddress(address);
505	        boolean duplicate = this.clinicService.findAllOwners().stream()
506	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
507	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())));
508	        if (duplicate) {
509	            throw new DuplicateOwnerHouseholdException(lastName, address);
510	        }
511	    }
512	
513	    /**
514	     * Assigns the owner being created a household identifier when the request opts into sharing a
515	     * household. The identifier is a stable value derived from the owner's normalized last name and
516	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
517	     * value regardless of creation order. Any already-existing owner in the same household that has no
518	     * identifier yet is back-filled with the same value so the whole household stays consistent.
519	     *
520	     * @param owner the owner being created, whose household id is set in place
521	     */
522	    private void assignHousehold(Owner owner) {
523	        String householdId = householdId(owner.getLastName(), owner.getAddress());
524	        String normalizedLastName = normalizeForComparison(owner.getLastName());
525	        String normalizedAddress = normalizeAddress(owner.getAddress());
526	        for (Owner existing : this.clinicService.findAllOwners()) {
527	            if (existing.getHouseholdId() == null
528	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
529	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
530	                existing.setHouseholdId(householdId);
531	                this.clinicService.saveOwner(existing);
532	            }
533	        }
534	        owner.setHouseholdId(householdId);
535	    }
536	
537	    /**
538	     * Derives the stable household identifier for a given last name and address. The value is
539	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
540	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
541	     * the same household therefore always produce the same identifier.
542	     *
543	     * @param lastName the owner's last name
544	     * @param address the owner's address
545	     * @return the stable household identifier
546	     */
547	    private String householdId(String lastName, String address) {
548	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
549	        try {
550	            byte[] digest = MessageDigest.getInstance("SHA-256")
551	                .digest(key.getBytes(StandardCharsets.UTF_8));
552	            StringBuilder hex = new StringBuilder();
553	            for (int i = 0; i < 6; i++) {
554	                hex.append(String.format("%02X", digest[i]));
555	            }
556	            return "HH-" + hex;
557	        } catch (NoSuchAlgorithmException ex) {
558	            throw new IllegalStateException("SHA-256 not available", ex);
559	        }
560	    }
561	
562	    /**
563	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
564	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
565	     * result is lower-cased. A {@code null} value normalizes to the empty string.
566	     *
567	     * @param value the value to normalize, may be {@code null}
568	     * @return the normalized value
569	     */
570	    private String normalizeForComparison(String value) {
571	        if (value == null) {
572	            return "";
573	        }
574	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
575	    }
576	
577	    /**
578	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
579	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
580	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
581	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
582	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
583	     * that is stored, returned, and used for every address comparison (household duplicate detection
584	     * and the shared household id).
585	     *
586	     * @param address the raw address value from the submitted owner payload, may be {@code null}
587	     * @return the normalized address
588	     */
589	    private String normalizeAddress(String address) {
590	        if (address == null) {
591	            return "";
592	        }
593	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
594	        if (collapsed.isEmpty()) {
595	            return "";
596	        }
597	        String[] tokens = collapsed.split(" ");
598	        StringBuilder normalized = new StringBuilder();
599	        for (int i = 0; i < tokens.length; i++) {
600	            if (i > 0) {
601	                normalized.append(' ');
602	            }
603	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
604	        }
605	        return normalized.toString();
606	    }
607	}
